use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let left = input.as_array().unwrap();
    let right = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut left_index = 0;
    let mut right_index = 0;

    while left_index < left.len() && right_index < right.len() {
        let left_value = left[left_index].as_array().unwrap();
        let right_value = right[right_index].as_array().unwrap();
        let key = left_value[0].as_i64().unwrap();
        if key == right_value[0].as_i64().unwrap() {
            result.push(Value::from(left_value[1].as_i64().unwrap()));
            left_index += 1;
            right_index += 1;
        } else if key < right_value[0].as_i64().unwrap() {
            left_index += 1;
        } else {
            right_index += 1;
        }
    }

    Value::from(result)
}
